/* THROWAWAY #199. In-memory comparison; URL carries review choices only. */
const params=new URLSearchParams(location.search);
const s={v:['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A',lang:params.get('lang')==='en'?'en':'de',theme:params.get('theme')==='dark'?'dark':'light',kind:['screenshot','amo','promo','marquee','social'].includes(params.get('kind'))?params.get('kind'):'screenshot',slide:[0,1,2].includes(Number(params.get('slide')))?Number(params.get('slide')):0,tab:['images','icons','inventory'].includes(params.get('tab'))?params.get('tab'):'images'};
const $=q=>document.querySelector(q),L=(de,en)=>s.lang==='de'?de:en;
const dimensions=()=>({screenshot:[1280,800],amo:[1280,960],promo:[440,280],marquee:[1400,560],social:[1200,630]})[s.kind];
const scene=(slide=s.slide,thumb=false)=>{const [width,height]=dimensions();return `<div class="${thumb?'thumb-art':'stage'}" data-ratio="${width/height}"><iframe class="scene" title="${L('Entwurf','Design')} ${s.v} · ${slide+1}" width="${width}" height="${height}" sandbox="allow-same-origin" data-scene="${slide}" data-thumb="${thumb}"></iframe></div>`;};
const imageSize=(svg,size)=>svg.replace(/width="\d+" height="\d+"/,`width="${size}" height="${size}"`);
function icons(){return `<section class="card"><div class="tag">${L('GEMEINSAME ICONFAMILIE · KEIN NEUES LOGO','SHARED ICON FAMILY · SAME LOGO')}</div><h2>${L('Eine Marke, passende Größen.','One mark, suitable sizes.')}</h2><div class="icon-board">${[16,24,32,48,64,128].map(n=>`<div class="icon-cell">${imageSize(n<=32?DATA.icons.small:DATA.icons.full,n)}<small>${n} px</small></div>`).join('')}</div><p class="icon-note">${L('Bis 32 px: vereinfachte Tropfen, ohne Rand und Glanz. Ab 48 px: die volle gewählte Marke. Alle Farbwerte sind nach sRGB abgebildet.','Up to 32 px: simplified drops, without rim or sheen. At 48 px and above: the full selected mark. All colors are mapped to sRGB.')}</p></section><section class="section two"><div class="card"><h2>${L('Bei 16 px','At 16 px')}</h2><div class="optical" style="margin-top:24px"><figure>${imageSize(DATA.icons.full,16)}<figcaption>${L('Volle Marke verkleinert','Full mark reduced')}</figcaption></figure><figure>${DATA.icons.small}<figcaption>${L('Optische Fassung','Optical cut')}</figcaption></figure></div><p class="icon-note">${L('Die zweite Probe bleibt sichtbar; feine Lichtkanten entfallen. Einfarbig wird die Kontur bei kleinen Größen verstärkt.','The second sample stays visible; fine highlights are removed. Small monochrome artwork uses a stronger outline.')}</p></div><div class="card"><h2>${L('Maskierbares App-Icon','Maskable app icon')}</h2><div class="mask" style="margin-top:20px"><figure><div class="round">${DATA.icons.maskable}</div><figcaption>${L('Kreis','Circle')}</figcaption></figure><figure><div class="squircle">${DATA.icons.maskable}</div><figcaption>${L('Abgerundet','Rounded')}</figcaption></figure></div><p class="icon-note">${L('Eigenes optionales Asset mit geschützter Mitte; kein Ersatz für das Favicon.','Separate optional asset with a protected center; distinct from the favicon.')}</p></div></section><section class="section card"><h2>${L('Im Toolbar-Kontext','In toolbar context')}</h2><p class="icon-note">${L('Schematische Browserleisten, keine Store-Screenshots.','Schematic browser bars, not store screenshots.')}</p><div class="toolbar"><span class="fake-icons">← ↻</span><span class="url">example.invalid / article</span>${DATA.icons.small}${DATA.icons.monoLight}<span>⋮</span></div><div class="toolbar dark"><span class="fake-icons">← ↻</span><span class="url">example.invalid / article</span>${DATA.icons.small}${DATA.icons.monoDark}<span>⋮</span></div><p class="icon-note">${L('Chromium: farbige Standardfassung. Firefox: dunkle Marke auf heller Toolbar, helle Marke auf dunkler Toolbar.','Chromium: color default. Firefox: dark artwork on a light toolbar, light artwork on a dark toolbar.')}</p></section><section class="section two"><div class="card"><h2>${L('Store-Icon','Store icon')}</h2><div style="margin-top:20px">${DATA.icons.store}</div><p class="icon-note">${L('Chrome Web Store: 96 px Marke auf 128 px Fläche, mit 16 px transparentem Rand. Dieser Rand gehört nur in das Store-Asset.','Chrome Web Store: 96 px artwork on a 128 px canvas, with 16 px transparent padding. This padding belongs only to the store asset.')}</p></div><div class="card"><h2>${L('Farbtreue','Color mapping')}</h2><p class="icon-note">${L('Die OKLCH-Farben des bestehenden Logos werden bei gleicher Helligkeit und gleichem Farbton in den sRGB-Farbraum gebracht. Die Chroma wird nur dort reduziert, wo nötig.','The existing logo’s OKLCH colors are mapped to sRGB at the same lightness and hue. Chroma is reduced only where needed.')}</p><p class="icon-note">${L('Die abgestuften Farben gehören zur Logozeichnung. Die Produktflächen bleiben neutral.','The gradient belongs to the logo artwork. Product surfaces stay neutral.')}</p></div></section>`;}
function inventory(){return `<section class="card inventory"><h2>${L('Exportset und Einsatz','Export set and purpose')}</h2><table><thead><tr><th>${L('Asset','Asset')}</th><th>${L('Größen','Sizes')}</th><th>${L('Einordnung','Purpose')}</th></tr></thead><tbody><tr><td>Favicon</td><td>SVG · PNG 16 / 32 / 48 / 96 · ICO</td><td>${L('Browser und Suchergebnis','Browser and search result')}</td></tr><tr><td>Apple touch</td><td>180 × 180 PNG</td><td>${L('Gewählte Kompatibilitätsfassung','Chosen compatibility export')}</td></tr><tr><td>Web app</td><td>192 / 512 · any + maskable</td><td>${L('Optional; keine neue PWA-Zusage','Optional; no new PWA commitment')}</td></tr><tr><td>Extension</td><td>16 / 24 / 32 / 48 / 64 / 96 / 128</td><td>PNG · Chromium + Firefox</td></tr><tr><td>Toolbar</td><td>16 / 24 / 32 / 48 / 64</td><td>${L('Farbe + zwei einfarbige Fassungen','Color + two monochrome cuts')}</td></tr><tr><td>Store icons</td><td>CWS 128 · AMO 128 · Edge 300</td><td>${L('Getrennte Ränder; Edge optional','Separate padding; Edge optional')}</td></tr><tr><td>CWS screenshots</td><td>1280 × 800</td><td>${L('Drei Motive in DE/EN','Three stories in DE/EN')}</td></tr><tr><td>AMO candidates</td><td>1280 × 960</td><td>${L('4:3; aktuelle Uploadprüfung offen','4:3; live upload validation pending')}</td></tr><tr><td>Promo</td><td>440 × 280 · 1400 × 560</td><td>${L('Sprachneutraler CWS-Satz','Language-neutral CWS set')}</td></tr><tr><td>Social</td><td>1200 × 630</td><td>${L('DE/EN; gewähltes OG-Format','DE/EN; selected OG format')}</td></tr></tbody></table></section><div class="note">${L('Größen sind nicht pauschal Pflichtgrößen. Die Recherche unterscheidet Plattformanforderungen, Empfehlungen und unsere Exportentscheidungen. AMO-Vorgaben und X-Vorschaubilder müssen vor einer Veröffentlichung aktuell geprüft werden.','Sizes are not universally mandatory. The research distinguishes platform requirements, recommendations and export choices. AMO requirements and X preview behavior need current checks before publication.')}</div>`;}
function render(){
  document.documentElement.lang=s.lang;document.title=`Source Taster · ${s.v} ${L(...artNames[s.v])} · #199`;
  $('#review').innerHTML=`<div class="top"><div><span class="tag">#199 · ${L('ENTWURF','DESIGN PREVIEW')}</span><h1>${L('Marke im Einsatz','Brand in use')}</h1></div><div class="controls"><button data-action="lang">${L('EN','DE')}</button><button data-action="theme">${s.theme==='light'?L('Dunkel','Dark'):L('Hell','Light')}</button></div></div><p class="brief muted">${L('Ein Logo und dieselbe Produktgestaltung. Drei Kompositionen für Store- und Vorschaubilder.','One logo and the same product identity. Three compositions for store and preview images.')}</p><nav class="tabs" aria-label="${L('Bereich','Section')}">${[['images','Bilder','Images'],['icons','Icons','Icons'],['inventory','Exportset','Export set']].map(([id,de,en])=>`<button data-tab="${id}" aria-pressed="${s.tab===id}">${L(de,en)}</button>`).join('')}</nav>${s.tab==='images'?`<div class="controls"><label>${L('Format','Format')} <select id="kind">${[['screenshot','CWS · 1280 × 800'],['amo','AMO · 1280 × 960'],['promo','Promo · 440 × 280'],['marquee','Marquee · 1400 × 560'],['social','Social · 1200 × 630']].map(([id,t])=>`<option value="${id}" ${s.kind===id?'selected':''}>${t}</option>`).join('')}</select></label>${(s.kind==='screenshot'||s.kind==='amo')?`<label>${L('Motiv','Story')} <select id="slide">${stories[s.lang].map((t,i)=>`<option value="${i}" ${s.slide===i?'selected':''}>0${i+1} · ${t.label}</option>`).join('')}</select></label>`:''}</div>`:''}`;
  $('#switcher').innerHTML=`<button data-action="prev" aria-label="${L('Vorheriger Entwurf','Previous design')}">←</button><span><b>${s.v} · ${L(...artNames[s.v])}</b><small>${L('Bildkomposition','Image composition')} · ${s.lang.toUpperCase()} · ${s.theme}</small></span><button data-action="next" aria-label="${L('Nächster Entwurf','Next design')}">→</button>`;
  if(s.tab==='icons')$('#sheet').innerHTML=icons();
  else if(s.tab==='inventory')$('#sheet').innerHTML=inventory();
  else $('#sheet').innerHTML=scene()+`<div class="meta"><span>${L(...artNames[s.v])} · ${dimensions().join(' × ')} px</span><span class="view-name">${L('Designbeispiel · keine Veröffentlichung','Design example · not published')}</span></div>`+(s.kind==='screenshot'||s.kind==='amo'?`<div class="thumbs">${stories[s.lang].map((t,i)=>`<button class="thumb" data-slide="${i}" aria-pressed="${s.slide===i}"><span class="tag">0${i+1}</span>${scene(i,true)}<strong>${t.label}</strong></button>`).join('')}</div>`:'')+`<section class="section"><h2>${L('Eine zusammenhängende Bildserie','One connected image series')}</h2><p class="brief muted">${L('Die Aufnahmen stammen aus dem gewählten Prüfungsentwurf D. Dokumentkontext und Begleittexte sind als synthetische Designbeispiele gekennzeichnet. Für Store-Veröffentlichungen werden später aktuelle, tatsächlich verfügbare Funktionen aufgenommen.','The captures come from the selected checking design D. Document context and captions are labelled as synthetic design examples. Store publication later needs captures of the actual released capabilities.')}</p></section>`+(s.kind==='promo'||s.kind==='marquee'?`<div class="note">${L('Chrome-Promokacheln lassen sich nicht lokalisieren. Deshalb verwenden alle Fassungen denselben kurzen englischen Text.','Chrome promo tiles cannot be localized, so all versions use the same short English text.')}</div>`:'')+`<div class="note">${L('Auswahl offen. Die Bildsprache wird hier entschieden; die Prototypbilder werden nicht als echte Store-Aufnahmen veröffentlicht.','Selection pending. This review decides the image direction; prototype images will not be submitted as real store captures.')}</div>`;
  document.querySelectorAll('[data-scene]').forEach(f=>{
    const [width,height]=dimensions();const kind=s.kind==='amo'?'screenshot':s.kind;
    const html=`<!doctype html><html lang="${s.lang}"><head><meta charset="utf-8"><style>${artCss(DATA)}</style></head><body>${artMarkup(DATA,{v:s.v,lang:s.lang,theme:s.theme,kind,slide:Number(f.dataset.scene),width,height})}</body></html>`;
    f.srcdoc=html;
  });
  fit();const q=new URLSearchParams({variant:s.v,lang:s.lang,theme:s.theme,kind:s.kind,slide:s.slide,tab:s.tab});try{history.replaceState(null,'','?'+q);}catch{/* Embedded review keeps state in memory if history is unavailable. */}
}
function fit(){document.querySelectorAll('.scene').forEach(f=>{const scale=f.parentElement.clientWidth/Number(f.width);f.style.transform=`scale(${scale})`;f.parentElement.style.height=(Number(f.height)*scale)+'px';});}
window.addEventListener('resize',fit);
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='lang')s.lang=s.lang==='de'?'en':'de';if(action==='theme')s.theme=s.theme==='light'?'dark':'light';if(action==='next'||action==='prev'){const v=['A','B','C'];s.v=v[(v.indexOf(s.v)+(action==='next'?1:2))%3];}render();return;}const tab=e.target.closest('[data-tab]');if(tab){s.tab=tab.dataset.tab;render();return;}const slide=e.target.closest('button[data-slide]');if(slide){s.slide=Number(slide.dataset.slide);render();}});
document.addEventListener('change',e=>{if(e.target.id==='kind')s.kind=e.target.value;else if(e.target.id==='slide')s.slide=Number(e.target.value);else return;render();});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]')||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();document.querySelector(`[data-action=${e.key==='ArrowLeft'?'prev':'next'}]`).click();}});
render();
